function applyPatch(doc: Record<string, any>, ops: Op[]): Record<string, any> {
  for (const o of ops) {
    const keys = o.path.split(".");
    const last = keys.pop()!;
    let node = doc;
    for (const k of keys) node = node[k] ??= {};
    if (o.op === "set") node[last] = o.value;
    else delete node[last];
  }
  return doc;
}

// Test driver (leave as is).
