coding.referenceSolution:
type Op = { op: "set"; path: string; value: unknown } | { op: "delete"; path: string };

function applyPatch(doc: Record<string, any>, ops: Op[]): Record<string, any> {
  const setIn = (node: any, keys: string[], o: Op): any => {
    const [head, ...rest] = keys;
    const copy = { ...(node ?? {}) };
    if (rest.length === 0) {
      if (o.op === "set") copy[head] = o.value;
      else delete copy[head];
      return copy;
    }
    if (o.op === "delete" && (copy[head] === undefined || copy[head] === null)) return copy;
    copy[head] = setIn(copy[head], rest, o);
    return copy;
  };
  return ops.reduce((acc, o) => setIn(acc, o.path.split("."), o), doc);
}

// Test driver (leave as is).
function patchDriver(doc: Record<string, any>, ops: Op[]) {
  const before = JSON.stringify(doc);
  const result = applyPatch(doc, ops);
  return { result, untouched: JSON.stringify(doc) === before };
}

